import hashlib,json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
d=json.loads((root/'evidence/overlap_entry_redteam_work3.json').read_text(encoding='utf-8'))
assert len(d['entries'])==19
assert d['disputed_flow_label_count']==12 and d['disputed_94ac0_pool_count']==8
rows=[]
for e in d['entries']:
 refs={(x['source'],x['mnemonic'],x['target']) for x in e['incoming_direct_control_flow']}
 calls=[r for r in refs if r[1]=='call']
 assert not calls, (e['address'],calls)
 owners=','.join(e['owner_seed_addresses'])
 mn=','.join(sorted({r[1] for r in refs}))
 rows.append(f"| `{e['address']}` | `{e['map_name'] or '—'}` | `{e['classification']}` | {len(refs)} | `{mn}` | `{owners}` | `{e['raw_bytes'][:16]}` |")
report=['# W3-012 — red-team of CFG flow labels and ambiguous entries','',f"Target SHA-256 `{d['target_sha256']}`; MAIN.MAP SHA-256 `{d['map_sha256']}`; decoder SHA-256 `{d['decoder_sha256']}`.",'',f"The CFG replay recovered {d['recovered_cfg_count']} candidates. It examined {d['disputed_flow_label_count']} MAP flow-label edges across 12 unique `def_`/`jpt_` addresses and all {d['disputed_94ac0_pool_count']} alternatives for the missing edge in owner `0x00094AC0`.",'','Each of the 19 distinct candidate addresses is an instruction start in one or more recovered CFGs and has at least one direct conditional/unconditional branch edge. The independent decoder scan found **zero direct CALL references** to any of them. The 12 `def_`/`jpt_` names are reached by conditional or unconditional branches from inside their owner CFGs, supporting compiler-flow-label classification.','',"The eight `0x94AC0` alternatives are unnamed instruction entries except `0x94D98` (`def_94D56`). Several are jump targets inside the overlapping `0x94AC0` / `0x954A0` CFGs; `0x95490` starts with `RET` and has a conditional branch into it. There are no direct CALL references. That does not exclude indirect calls, so none is promoted to a function.",'','| Address | MAIN.MAP label | Classification | Distinct incoming branch instructions | Branch kinds | Owner seeds | Bytes |','|---|---|---|---:|---|---|---|',*rows,'',"No native invocation was attempted: the instruction entries lack an independently measured register/stack contract, and branch entry alone does not define a callable ABI. No exact extent fixture or differential PASS justifies increasing the confirmed function count. The historical one-of-eight membership ambiguity remains bounded and unresolved as recorded in W3-011.",'','Evidence: `evidence/overlap_entry_redteam_work3.json`. Reproduction: `py -3 tools/audit_overlap_entries_work3.py` (full CFG replay; uses the read-only Capstone environment).','']
(root/'reports/coordination/overlap_entry_redteam_work3.md').write_text('\n'.join(report),encoding='utf-8')
test='''import hashlib,json\nfrom pathlib import Path\nroot=Path(__file__).resolve().parents[1]\nd=json.loads((root/'evidence/overlap_entry_redteam_work3.json').read_text(encoding='utf-8'))\ndelta=json.loads((root/'evidence/overlap_delta_work3.json').read_text(encoding='utf-8'))\nassert hashlib.sha256((root/'evidence/genewars-1_1.exe').read_bytes()).hexdigest()==d['target_sha256']\nassert d['target_count']==len(d['entries'])==19\nlabels=[e for e in d['entries'] if e['classification']=='def_/jpt_ map control-flow label']\nassert len(labels)==12 and d['disputed_flow_label_count']==12\nassert len(delta['bounded_ambiguous_edge'][0]['candidate_pool'])==8\nassert all(e['incoming_direct_control_flow'] for e in d['entries'])\nassert all(x['mnemonic']!='call' for e in d['entries'] for x in e['incoming_direct_control_flow'])\nassert all(e['instruction_start_in_cfg_count']>0 for e in d['entries'])\nassert d['function_count_adjustment']==0\nprint('PASS: 12 flow-label addresses, 8 ambiguous candidates, branch-only incoming edges, no function promotions')\n'''
(root/'tests/test_overlap_entry_redteam_work3.py').write_text(test,encoding='utf-8')
print({'entries':len(rows),'flow_label_edges':sum(len({(x['owner_seed'],x['candidate']) for x in json.loads((root/'evidence/nonmap_overlap_edges_work3.json').read_text())['edges'] if x['classification']=='MAP_control_flow_label'}) for _ in [0]),'candidate_count':d['target_count'],'call_refs':0})
